<script setup lang="ts">
import RecordPagination from '../components/RecordPagination.vue'
const pageSize = ref(20)
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { ElMessageBox } from 'element-plus'
import ReadOnlyDocument from '../components/ReadOnlyDocument.vue'
import { listReferences, getReference, setReferenceEnabled, retryReference, referenceLabel, type Reference, type ReferenceSnapshot, type ReferencePage } from '../api/references'
const data = ref<ReferencePage>(), page = ref(1), q = ref(''), loading = ref(false), error = ref(''), busy = ref<string[]>([]), detail = ref<ReferenceSnapshot>(), detailOpen = ref(false)
const keys = new Map<string, string>(); let timer: ReturnType<typeof setTimeout> | undefined, active = true, generation = 0
const pending = computed(() => data.value?.items.some(row => ['QUEUED','PROCESSING','PREPARED'].includes(row.processingStatus) || (row.requestedEnabled !== row.effectiveEnabled && row.processingStatus !== 'FAILED' && data.value?.latestGeneration?.status !== 'FAILED')) || data.value?.latestGeneration?.status === 'BUILDING')
const indexLabel: Record<string,string> = { BUILDING:'构建中', READY:'准备完成', ACTIVE:'已启用', ARCHIVED:'已归档', FAILED:'构建失败' }
function failures(row: Reference) { return Object.keys(row.parts).filter(key => row.parts[key]?.status === 'FAILED') }
function switchLabel(row: Reference) { if(row.requestedEnabled === row.effectiveEnabled) return ''; if(row.processingStatus === 'FAILED') return '无可用内容，启用未生效'; if(data.value?.latestGeneration?.status === 'FAILED') return row.requestedEnabled ? '启用切换失败' : '停用切换失败'; return row.requestedEnabled ? '启用待切换' : '停用待切换' }
function partLabel(row: Reference, key: string) { if(key === 'BODY') return '正文';const node = key.slice(key.indexOf(':') + 1);return `配图${row.imageNumbers?.[node] ?? ''}${key.startsWith('IMAGE:') ? '特征' : 'OCR文字'}` }
async function load(reset = false) { if (timer) clearTimeout(timer); if (reset) page.value = 1; const current = ++generation; loading.value = true; error.value = ''; try { const value = await listReferences(page.value, q.value, pageSize.value); if (!active || current !== generation) return; data.value = value; if (pending.value) timer = setTimeout(() => load(), 3000) } catch (failure) { if (active && current === generation) error.value = failure instanceof Error ? failure.message : '读取失败' } finally { if (current === generation) loading.value = false } }
async function toggle(row: Reference) {
  if (busy.value.includes(row.referenceId)) return
  try { await ElMessageBox.confirm(`确认${row.requestedEnabled ? '停用' : '启用'}“${row.title}”？新索引切换后影响后续检测，历史报告保留。`, '参考作品启停', { confirmButtonText: '确认', cancelButtonText: '取消' }) } catch { return }
  const signature = `enable:${row.referenceId}:${!row.requestedEnabled}`; if (!keys.has(signature)) keys.set(signature, crypto.randomUUID()); busy.value.push(row.referenceId)
  try { await setReferenceEnabled(row.referenceId, keys.get(signature)!, !row.requestedEnabled); keys.delete(signature); await load() } catch (failure) { error.value = failure instanceof Error ? failure.message : '启停请求未确认' } finally { busy.value = busy.value.filter(id => id !== row.referenceId) }
}
async function retry(row: Reference, index = false, selectedParts?: string[]) { const parts = index ? [] : selectedParts ?? failures(row), signature = `retry:${row.referenceId}:${parts.join(',')}`; if (!keys.has(signature)) keys.set(signature, crypto.randomUUID()); busy.value.push(row.referenceId); try { await retryReference(row.referenceId, keys.get(signature)!, parts); keys.delete(signature); await load() } catch (failure) { error.value = failure instanceof Error ? failure.message : '重试失败' } finally { busy.value = busy.value.filter(id => id !== row.referenceId) } }
async function view(row: Reference) { try { detail.value = await getReference(row.referenceId); detailOpen.value = true } catch (failure) { error.value = failure instanceof Error ? failure.message : '读取失败' } }
onMounted(() => load()); onBeforeUnmount(() => { active = false; if (timer) clearTimeout(timer) })
</script>
<template><div class="panel"><div class="list-filters"><el-input v-model="q" aria-label="搜索参考标题" placeholder="搜索参考标题" @keyup.enter="load(true)" /><el-button @click="load(true)">查询</el-button><el-button @click="load()">刷新</el-button><RouterLink to="/references/new"><el-button type="primary">添加参考作品</el-button></RouterLink></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><p class="muted">当前检索版本：{{ data?.activeGenerationId || '尚未启用' }} · 最新构建：{{ data?.latestGeneration ? indexLabel[data.latestGeneration.status] : '暂无' }}</p><el-alert v-if="data?.latestGeneration?.status === 'FAILED'" title="索引构建失败，当前检索继续使用原版本；可重试索引切换。" type="error" :closable="false" /><el-table v-loading="loading" :data="data?.items ?? []" empty-text="暂无参考作品"><el-table-column type="expand"><template #default="{row}"><div class="reference-parts"><p>录入：{{ row.createdByName }} · {{ new Date(row.createdAt).toLocaleString('zh-CN') }}</p><p v-if="row.originalPublishedAt">原发布时间：{{ new Date(row.originalPublishedAt).toLocaleString('zh-CN') }}</p><p v-if="row.sourceMetadata.sourceOrganization">来源组织：{{ row.sourceMetadata.sourceOrganization }}</p><a v-if="row.sourceMetadata.url" :href="row.sourceMetadata.url" target="_blank" rel="noopener noreferrer">{{ row.sourceMetadata.url }}</a><p v-if="row.sourceMetadata.description">{{ row.sourceMetadata.description }}</p><p v-if="row.sourceMetadata.imageSources?.some((entry: {importStatus?: string}) => entry.importStatus === 'REJECTED')" class="unsaved">部分原图超过导入限额，未纳入本条目；原来源信息已保留。</p><div v-for="(part, key) in row.parts" :key="key" class="part-row"><span>{{ partLabel(row,String(key)) }}</span><el-tag effect="plain" :type="part.status === 'FAILED' ? 'danger' : 'info'">{{ referenceLabel[part.status] || part.status }}</el-tag><span v-if="part.result?.ocrStatus === 'EMPTY'" class="muted">未识别到文字，不影响已成功的图片特征</span><span v-if="part.errorCode" class="muted">{{ part.errorCode }}</span><el-button v-if="part.status === 'FAILED'" size="small" :disabled="busy.includes(row.referenceId)" @click="retry(row,false,[String(key)])">重试该部分</el-button></div></div></template></el-table-column><el-table-column label="参考标题" min-width="230"><template #default="{row}"><el-button link type="primary" @click="view(row)">{{ row.title }}</el-button></template></el-table-column><el-table-column label="来源" width="110"><template #default="{row}">{{ row.originType === 'PUBLISHED' ? '站内发布' : '管理员导入' }}</template></el-table-column><el-table-column label="处理状态" width="140"><template #default="{row}"><el-tag effect="plain" :type="row.processingStatus === 'PARTIAL' ? 'warning' : row.processingStatus === 'FAILED' ? 'danger' : 'info'">{{ referenceLabel[row.processingStatus] || row.processingStatus }}</el-tag></template></el-table-column><el-table-column label="实际检索状态" width="170"><template #default="{row}"><div>{{ row.effectiveEnabled ? '当前可检索' : '当前不参与检索' }}</div><small v-if="switchLabel(row)" class="unsaved">{{ switchLabel(row) }}</small></template></el-table-column><el-table-column label="操作" min-width="210"><template #default="{row}"><el-button size="small" :disabled="busy.includes(row.referenceId)" @click="toggle(row)">{{ row.requestedEnabled ? '停用' : '启用' }}</el-button><el-button v-if="failures(row).length || row.processingStatus === 'FAILED'" size="small" :disabled="busy.includes(row.referenceId) || row.processingStatus === 'QUEUED'" @click="retry(row)">重试失败部分</el-button><el-button v-else-if="data?.latestGeneration?.status === 'FAILED'" size="small" :disabled="busy.includes(row.referenceId)" @click="retry(row,true)">重试索引切换</el-button></template></el-table-column></el-table><RecordPagination v-model:current-page="page" v-model:page-size="pageSize" :total="data?.total ?? 0" @change="load()" /></div><el-dialog v-model="detailOpen" title="参考作品内容" width="min(900px, 95vw)"><ReadOnlyDocument v-if="detail" :document="detail" /></el-dialog></template>
